async function loadNilaiKegiatan(){const[a,n]=await Promise.all([api("/api/kegiatan"),api("/api/settings").catch(()=>({}))]),i=new Date(Date.now()+252e5),t=n.active_month||i.toISOString().slice(0,7);$("main").innerHTML=`<div class="page-header fade-up"><h2><i class="ri-star-line"></i> Nilai Kegiatan</h2>\n    <p style="color:var(--t3);margin-top:.3rem">Pilih kegiatan, kelompok, dan bulan untuk input nilai</p></div>\n    <div class="card fade-up"><div style="display:flex;gap:.8rem;flex-wrap:wrap;align-items:end">\n      <div class="fg" style="flex:2;min-width:150px"><label>Kegiatan</label>\n        <select id="nkKegiatan" onchange="nkUpdateKelompok(this)">\n          <option value="">- Pilih Kegiatan -</option>\n          ${a.map(a=>`<option value="${a.id}" data-nama="${a.nama.replace(/"/g,"&quot;")}">${a.nama}</option>`).join("")}\n        </select>\n      </div>\n      <div class="fg" style="flex:2;min-width:150px"><label>Kelompok</label>\n        <select id="nkKelompok"><option value="">- Pilih Kegiatan Dulu -</option></select>\n      </div>\n      <div class="fg" style="flex:1;min-width:100px"><label>Bulan</label><input type="month" id="nkBulan" value="${t}"></div>\n      <button class="btn btn-primary btn-sm" onclick="nkLoadTable()"><i class="ri-search-line"></i> Tampilkan</button>\n    </div></div>\n    <div id="nkTableArea"></div>`}async function nkUpdateKelompok(a){const n=$("nkKelompok");if(!a.value)return void(n.innerHTML='<option value="">- Pilih Kegiatan Dulu -</option>');const i=a.options[a.selectedIndex].getAttribute("data-nama");n.innerHTML='<option value="">Loading...</option>';try{const a=(await api("/api/kelompok")).filter(a=>a.kegiatan_nama===i||a.tipe===i);n.innerHTML=a.length?a.map(a=>`<option value="${a.id}" data-nama="${a.nama.replace(/"/g,"&quot;")}">${a.nama}</option>`).join(""):'<option value="">Belum ada kelompok</option>'}catch(a){n.innerHTML='<option value="">Error</option>'}}async function nkLoadTable(){const a=$("nkKegiatan").value,n=$("nkKelompok").value,i=$("nkBulan").value;if(!a||!n||!i)return toast("Pilih kegiatan, kelompok dan bulan");const t=$("nkKegiatan").options[$("nkKegiatan").selectedIndex].text,e=$("nkKelompok").options[$("nkKelompok").selectedIndex].text;var[l,o]=await Promise.all([api("/api/kelompok/"+n+"/members"),api("/api/nilai-kegiatan?kelompok_id="+n+"&bulan="+i+"&kegiatan_id="+a)]),r={};(o||[]).forEach(function(a){r[a.santri_id]={nilai:a.nilai,catatan:a.catatan||""}});var s=o&&o.length>0,d=l.map(function(a){var n=r[a.santri_id]||{nilai:"",catatan:""};return'<tr data-sid="'+a.santri_id+'"><td>'+a.santri_nama+'</td><td style="width:90px"><input type="number" class="nk-nilai" min="0" max="100" step="0.1" value="'+(n.nilai||"")+'" placeholder="0-100" style="width:100%;padding:.4rem .5rem;border-radius:8px;border:1.5px solid var(--border);font-size:.82rem;text-align:center"></td><td><input type="text" class="nk-catatan" value="'+n.catatan.replace(/"/g,"&quot;")+'" placeholder="Opsional..." style="width:100%;padding:.4rem .5rem;border-radius:8px;border:1.5px solid var(--border);font-size:.82rem"></td></tr>'}).join("");$("nkTableArea").innerHTML=`\n    <div class="card au">\n    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:.6rem;flex-wrap:wrap;gap:.5rem">\n    <h3 style="margin:0"><i class="ri-edit-line"></i> Input Nilai (${l.length} santri)</h3>\n    <div style="display:flex;gap:.3rem">\n    <button class="btn btn-outline btn-sm" onclick="nkSetAll(100)"><i class="ri-checkbox-circle-line"></i> Semua 100</button>\n    <button class="btn btn-outline btn-sm" onclick="nkSetAll(0)"><i class="ri-close-circle-line"></i> Reset</button>\n    </div></div>\n    ${s?'<div class="info-box success" style="margin-bottom:.8rem"><i class="ri-checkbox-circle-line"></i> Nilai sudah diinput untuk bulan ini. Anda bisa memperbarui.</div>':""}\n    <div class="table-wrap"><table>\n    <tr><th>Nama Santri</th><th style="text-align:center;width:90px">Nilai</th><th>Catatan</th></tr>\n    ${d}\n    ${l.length?"":'<tr><td colspan="3" style="text-align:center;color:var(--t3)">Belum ada anggota</td></tr>'}\n    </table></div>\n    <button class="btn btn-primary" id="btnNkSave" onclick="nkSimpan(${a},${n})" style="margin-top:1rem"><i class="ri-save-line"></i> Simpan Nilai</button></div>`,window._nkState={kegId:a,kegNama:t,kelId:n,kelNama:e,bulan:i}}function nkSetAll(a){document.querySelectorAll(".nk-nilai").forEach(function(n){n.value=a})}async function nkSimpan(a,n){var i=window._nkState?.bulan||$("nkBulan")?.value,t=document.querySelectorAll("tr[data-sid]"),e=[];if(t.forEach(function(a){var n=parseInt(a.getAttribute("data-sid")),i=parseFloat(a.querySelector(".nk-nilai").value)||0,t=a.querySelector(".nk-catatan").value||"";e.push({santri_id:n,nilai:i,catatan:t})}),!e.length)return toast("Tidak ada data");var l=$("btnNkSave");l&&(l.disabled=!0,l.innerHTML='<i class="ri-loader-4-line"></i> Menyimpan...',l.style.opacity=".6");try{var o=await api("/api/nilai-kegiatan/bulk",{method:"POST",body:JSON.stringify({kegiatan_id:a,kelompok_id:n,bulan:i,data:e})});toast("✅ "+(o.message||"Nilai disimpan")),l&&(l.innerHTML='<i class="ri-checkbox-circle-line"></i> Tersimpan',l.style.background="var(--green)",l.style.opacity=".7")}catch(a){l&&(l.disabled=!1,l.innerHTML='<i class="ri-save-line"></i> Simpan Nilai',l.style.opacity="1"),toast("Error: "+a.message)}}